// Package output provides the helpers shared by every code renderer:
// import management, formatting and writing generated files.
package output

import (
	"bytes"
	"fmt"
	"go/format"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// Header is the first line of every file generated by datlas.
// It follows https://go.dev/s/generatedcode so tools recognise the file as generated.
const Header = "// Code generated by datlas. DO NOT EDIT."

// IsGenerated reports whether src is a file generated by datlas.
func IsGenerated(src []byte) bool {
	return bytes.HasPrefix(src, []byte(Header))
}

// Imports tracks the packages a generated file depends on and assigns
// each of them a unique local name.
type Imports struct {
	self     string
	byPath   map[string]string
	used     map[string]bool
	reserved map[string]bool
}

// NewImports returns an import set for a file that belongs to the package selfPath.
// reserved lists identifiers that must not be used as import names,
// such as the top-level identifiers of the package the file is written into.
func NewImports(selfPath string, reserved ...string) *Imports {
	im := &Imports{
		self:     selfPath,
		byPath:   map[string]string{},
		used:     map[string]bool{},
		reserved: map[string]bool{},
	}
	for _, r := range reserved {
		im.reserved[r] = true
	}
	return im
}

// Add registers the package at path whose declared name is name and returns
// the identifier the generated code must use to refer to it.
// It returns an empty string for the package the file belongs to.
func (im *Imports) Add(path, name string) string {
	if path == im.self {
		return ""
	}
	if alias, ok := im.byPath[path]; ok {
		return alias
	}
	alias := name
	for i := 2; im.used[alias] || im.reserved[alias]; i++ {
		alias = name + strconv.Itoa(i)
	}
	im.byPath[path] = alias
	im.used[alias] = true
	return alias
}

// Qualifier is a types.Qualifier that registers every package it sees.
func (im *Imports) Qualifier(p *types.Package) string {
	return im.Add(p.Path(), p.Name())
}

// TypeString renders t as Go source, importing the packages it refers to.
func (im *Imports) TypeString(t types.Type) string {
	return types.TypeString(t, im.Qualifier)
}

// Decl renders the import declaration, or an empty string when nothing is imported.
func (im *Imports) Decl() string {
	if len(im.byPath) == 0 {
		return ""
	}
	paths := make([]string, 0, len(im.byPath))
	for p := range im.byPath {
		paths = append(paths, p)
	}
	sort.Strings(paths)

	var std, others []string
	for _, p := range paths {
		if isStdlib(p) {
			std = append(std, p)
		} else {
			others = append(others, p)
		}
	}

	var b strings.Builder
	b.WriteString("import (\n")
	for i, p := range append(std, others...) {
		if i == len(std) && i > 0 {
			b.WriteString("\n")
		}
		alias := im.byPath[p]
		if alias == defaultName(p) {
			fmt.Fprintf(&b, "\t%q\n", p)
		} else {
			fmt.Fprintf(&b, "\t%s %q\n", alias, p)
		}
	}
	b.WriteString(")\n")
	return b.String()
}

// isStdlib reports whether path looks like a standard library package.
func isStdlib(path string) bool {
	first, _, _ := strings.Cut(path, "/")
	return !strings.Contains(first, ".")
}

// defaultName guesses the name a package is imported as without an alias.
// Guessing wrong is harmless: it only adds a redundant alias.
func defaultName(path string) string {
	base := path[strings.LastIndex(path, "/")+1:]
	if len(base) > 1 && base[0] == 'v' && isDigits(base[1:]) {
		if i := strings.LastIndex(path[:len(path)-len(base)-1], "/"); i >= 0 {
			base = path[i+1 : len(path)-len(base)-1]
		}
	}
	return base
}

func isDigits(s string) bool {
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return s != ""
}

// File assembles a complete generated Go file.
func File(pkgName string, imports *Imports, body []byte) []byte {
	var b bytes.Buffer
	b.WriteString(Header)
	b.WriteString("\n\n")
	fmt.Fprintf(&b, "package %s\n\n", pkgName)
	b.WriteString(imports.Decl())
	b.WriteString("\n")
	b.Write(body)
	return b.Bytes()
}

// Result is the outcome of a generator: the file to write, or the stale file to remove.
type Result struct {
	// Path is the generated file.
	Path string
	// Src is the unformatted content of the file. Nil means the file must be removed.
	Src []byte
}

// Format formats src with go/format.
func Format(path string, src []byte) ([]byte, error) {
	formatted, err := format.Source(src)
	if err != nil {
		return nil, fmt.Errorf("format generated code for %s: %w\n%s", path, err, src)
	}
	return formatted, nil
}

// Apply writes or removes the file described by r and returns a message describing what it did.
// Files that were not generated by datlas are never overwritten or removed.
//
// When check is true, Apply changes nothing and instead returns an error if the file on disk
// differs from r, which lets CI verify that generated code is up to date.
func Apply(r Result, check bool) (string, error) {
	existing, err := os.ReadFile(r.Path)
	exists := err == nil
	if err != nil && !os.IsNotExist(err) {
		return "", err
	}
	if exists && !IsGenerated(existing) {
		return "", fmt.Errorf("%s exists but was not generated by datlas; refusing to modify it", r.Path)
	}

	if r.Src == nil {
		switch {
		case !exists:
			return "", nil
		case check:
			return "", fmt.Errorf("%s is stale and must be removed; run datlas to update it", r.Path)
		}
		if err := os.Remove(r.Path); err != nil {
			return "", err
		}
		return "removed stale " + r.Path, nil
	}

	formatted, err := Format(r.Path, r.Src)
	if err != nil {
		return "", err
	}
	if check {
		if !exists || !bytes.Equal(existing, formatted) {
			return "", fmt.Errorf("%s is out of date; run datlas to update it", r.Path)
		}
		return r.Path + " is up to date", nil
	}
	if err := os.MkdirAll(filepath.Dir(r.Path), 0o755); err != nil {
		return "", err
	}
	if err := os.WriteFile(r.Path, formatted, 0o644); err != nil {
		return "", err
	}
	return "wrote " + r.Path, nil
}
